using System;
using System.Collections.Generic;

namespace Game_Catalog.Models
{
    /// <summary> Represents a video game of the library or the archive. </summary>
    public class Game
    {
        /// <summary> Unique identifier of the game. Generated by the database. </summary>
        public int GameId { get; set; }

        /// <summary> Identifier of the developer studio. </summary>
        public int DeveloperId { get; set; }

        private string _developerName = string.Empty;
        /// <summary> Name of the developer studio, loaded together with the game. </summary>
        public string DeveloperName
        {
            get => _developerName;
            set => _developerName = value ?? string.Empty;
        }

        /// <summary> Identifier of the base game if this game is a DLC. Null for standalone games. </summary>
        public int? ParentGameId { get; set; }

        private string _gameTitle = string.Empty;
        /// <summary> Title of the game. </summary>
        public string GameTitle
        {
            get => _gameTitle;
            set => _gameTitle = value ?? string.Empty;
        }

        private string _gameDescription = string.Empty;
        /// <summary> Description of the game. Empty means no description. </summary>
        public string GameDescription
        {
            get => _gameDescription;
            set => _gameDescription = value ?? string.Empty;
        }

        /// <summary> Release year. Null if unknown. </summary>
        public int? ReleaseYear { get; set; }

        /// <summary> Current playing status. </summary>
        public GameStatus GameStatus { get; set; } = GameStatus.Planned;

        /// <summary> Size on disk in GB. Null if the game is not installed or not measured. </summary>
        public double? SizeGB { get; set; }

        /// <summary> Personal rating from 1 to 10. Null if not rated. </summary>
        public int? PersonalRating { get; set; }

        private string _coverImagePath = string.Empty;
        /// <summary> Local path to the cover image. Empty means none. </summary>
        public string CoverImagePath
        {
            get => _coverImagePath;
            set => _coverImagePath = value ?? string.Empty;
        }

        private string _backgroundImagePath = string.Empty;
        /// <summary> Local path to the background image. Empty means none. </summary>
        public string BackgroundImagePath
        {
            get => _backgroundImagePath;
            set => _backgroundImagePath = value ?? string.Empty;
        }

        private string _executablePath = string.Empty;
        /// <summary> Local path to the game executable. Empty means none. </summary>
        public string ExecutablePath
        {
            get => _executablePath;
            set => _executablePath = value ?? string.Empty;
        }

        private string _installPath = string.Empty;
        /// <summary> Local path to the install folder. Empty means the game is not installed. </summary>
        public string InstallPath
        {
            get => _installPath;
            set => _installPath = value ?? string.Empty;
        }

        private string _iconPath = string.Empty;
        /// <summary> Local path to the small icon. Empty means none. </summary>
        public string IconPath
        {
            get => _iconPath;
            set => _iconPath = value ?? string.Empty;
        }

        /// <summary> Date and time the game was added to the library. </summary>
        public DateTime AddedAt { get; set; } = DateTime.Now;

        /// <summary> Whether the game is archived. </summary>
        public bool IsArchived { get; set; }

        /// <summary> Total hours of finished sessions. Computed by the database, not stored. </summary>
        public double TotalHours { get; set; }

        /// <summary> Whole days since the game was added. Computed by the database, not stored. </summary>
        public int DaysInLibrary { get; set; }

        /// <summary> Genres of the game. </summary>
        public List<Genre> Genres { get; set; } = new();

        /// <summary> Platforms of the game. </summary>
        public List<Platform> Platforms { get; set; } = new();

        /// <summary> Tags of the game. </summary>
        public List<Tag> Tags { get; set; } = new();
    }
}